blocks.text:
:root { --spazio-sezione: 2rem; }
.compact { --spazio-sezione: 1rem; }
.sezione { padding-block: var(--spazio-sezione); }

/* Una .sezione dentro .compact eredita il valore locale. */

.sezione {
  padding-block: var(--spazio-sezione, 2rem);
}
/* Il fallback entra in gioco se la variabile non è disponibile. */

@import "tailwindcss";
@theme {
  --color-laboratorio: oklch(45% 0.085 224);
}
/* bg-laboratorio e text-laboratorio usano questo token. */

@import "tailwindcss";
@plugin "daisyui" {
  themes: light --default, dark;
}
/* Il tema scuro è disponibile; qui non è selezionato automaticamente. */

@plugin "daisyui/theme" {
  name: "light";
  --radius-box: 1rem;
  --radius-field: 0.5rem;
  --radius-selector: 0.25rem;
}
/* Gli altri valori del tema light restano ereditati. */
